   Пример работы с объектом WeakReference



     Пример обнуления объекта WeakReference после уничтожения исходного объекта


<?php

$obj = new stdClass();
$weakref = WeakReference::create($obj);

var_dump($weakref->get());

unset($obj);

var_dump($weakref->get());


